import { ClassLevelId, Difficulty } from '../../types';
import { buildSubjectHyper72, HyperBundle, HyperTopicTuple, mergeHyperBundles } from './engine';

type CompactItem = [
  slug: string,
  title: string,
  keyNotion: string,
  rule: string,
  trap: string,
  cls: ClassLevelId,
  diff?: Difficulty
];

function expandTopics(subjectLabel: string, items: CompactItem[]): HyperTopicTuple[] {
  return items.map(([slug, title, keyNotion, rule, trap, cls, diff]) => [
    slug,
    title,
    `Programme complet sur « ${title} » en ${subjectLabel} : mécanismes clés, méthodes d’analyse et applications évaluées.`,
    keyNotion,
    rule,
    trap,
    `Application corrigée (${cls.toUpperCase()}) : mobiliser « ${rule} » dans l’étude de ${title}.`,
    diff ??
      (cls === '6e' || cls === '5e' || cls === '4e' || cls === '3e'
        ? 'facile'
        : cls === 'l3' || cls === 'master'
          ? 'difficile'
          : 'moyen'),
    cls,
  ]);
}

